INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 1, 'This recipe calls for asian eggplants, or Japanese eggplants. They are long and thin compared to a European or globe eggplant, and much more tender and delicate. If you can''t find them you can substitute globe eggplant, but the dish is really best with the asian eggplant.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 2, '*A lot of grocery stores have Asian ingredient aisles now. You should be able to find chili-bean paste, a mixture of preserved chilies mixed with mashed soybeans, there or at any Asian market. (Do not confuse with black bean paste or chili-garlic paste.)');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 3, '**Sichuan peppercorns are available at some stores and online for quite cheap. They aren''t spicy like other peppers but rather have a citrusy flavor and induce a tingly, numbing sensation like a carbonated drink.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 4, 'Prep eggplant, chili sauce, cornstarch slurry, vinegar and scallions:');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 5, 'Begin your mise en place. Quarter the eggplant lengthwise and chop into large batons and set aside.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 6, 'In a small bowl, mix together the chicken stock, sugar, and soy sauce and set it aside.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 7, 'In a second bowl, mix together the chili bean paste, garlic, ginger, and sichuan peppercorns and set it aside.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 8, 'In a third bowl, mix together the cornstarch with a tablespoon of water and set it aside.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 9, 'Lastly, in a fourth bowl, mix together the scallions and vinegar and set it aside.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 10, 'Sauté eggplant:');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 11, 'Place the oil in a wok or large sauté pan over medium-high heat until the oil is almost smoking. Add the eggplant and sauté, allowing it to sit for a few seconds each time you move it to allow it to brown and blister. If the eggplant absorbs all the oil and some pieces don''t get any then add a little more oil.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 12, 'Add the chili bean paste, garlic, ginger, and sichuan peppercorns and sauté:');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 13, 'until fragrant, about 30 seconds.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 14, 'Add the chicken stock mixture:');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 15, 'turn the heat to medium-low and simmer for 90 seconds.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 16, 'Add the cornstarch mixture:');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 17, 'and stir together until the sauce thickens a bit.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 18, 'Add the scallions and vinegar:');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 19, 'and cook for 15 seconds to diffuse their harsh flavors a bit.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d07e', 20, 'Garnish with cilantro and serve.');
INSERT INTO recipes (id, name, description, meal_type, servings) VALUES ('00000000-0000-4000-8000-00000000d07b', 'Sichuan Style Stir-Fried Chinese Long Beans', 'Danie: Chinese. Źródło: TheMealDB', 'lunch', 4) ON CONFLICT (id) DO NOTHING;
